-- FMH BATCH-2: attach 30 sales to existing units (atomic, verify-or-rollback)
BEGIN;

ALTER TABLE public.clients DISABLE TRIGGER USER;
ALTER TABLE public.sales DISABLE TRIGGER USER;
ALTER TABLE public.installments DISABLE TRIGGER USER;
ALTER TABLE public.payments DISABLE TRIGGER USER;
ALTER TABLE public.units DISABLE TRIGGER USER;

-- 1) new clients (16)

-- 2) sales (30)  [area_sqft=1, pps=gross, discount=file -> net lands exact]

-- 3) installments (1059)

-- 4) payments (125)

-- 5) mark the 30 units Sold (status only)
UPDATE public.units SET status_id='5723bb68-d558-41c8-92e5-10a0eaf6682b', updated_at=now() WHERE company_id='71d33e07-e55c-49af-8f5b-fdd7fd6e8612' AND project_id='ce05f4bb-a527-4e2b-b529-970c76c8d855' AND unit_no IN ('10-01','10-3','10-04','10-05','10-06','10-07','10-09','10-11','10-12','10-13','10-14','10-15','10-16','10-17','12-18','3-02','3-09','4-02','4-07','4-12','7-17','8-13','9-08','GF-54','LG-14','LG-15','LG-16','LG-17','LG-26','LG-34');

ALTER TABLE public.clients ENABLE TRIGGER USER;
ALTER TABLE public.sales ENABLE TRIGGER USER;
ALTER TABLE public.installments ENABLE TRIGGER USER;
ALTER TABLE public.payments ENABLE TRIGGER USER;
ALTER TABLE public.units ENABLE TRIGGER USER;

-- expected per-sale net/received
CREATE TEMP TABLE _chk(sale_no text PRIMARY KEY, net numeric, received numeric) ON COMMIT DROP;

-- ===== VERIFY (any failure -> RAISE -> rollback) =====
DO $v$
DECLARE
  CO   uuid := '71d33e07-e55c-49af-8f5b-fdd7fd6e8612';
  PROJ uuid := 'ce05f4bb-a527-4e2b-b529-970c76c8d855';
  SOLD uuid := '5723bb68-d558-41c8-92e5-10a0eaf6682b';
  AVAIL uuid := '839b6149-d3ef-4c49-94be-c51e5d638b31';
  n int; m int; bn numeric; br numeric; fp text;
BEGIN
  -- a) 30 batch-2 sales created, valid (NOT NULL) unit_id+client_id
  SELECT count(*) INTO n FROM sales s JOIN _chk c ON c.sale_no=s.sale_number
    WHERE s.company_id=CO AND s.status='active' AND s.unit_id IS NOT NULL AND s.client_id IS NOT NULL;
  IF n<>30 THEN RAISE EXCEPTION 'CHECK a FAIL: batch-2 valid sales = % (want 30)', n; END IF;

  -- b) per-sale net == file net
  SELECT count(*) INTO n FROM sales s JOIN _chk c ON c.sale_no=s.sale_number
    WHERE s.company_id=CO AND s.net_amount <> c.net;
  IF n<>0 THEN RAISE EXCEPTION 'CHECK b FAIL: net mismatches = %', n; END IF;

  -- c) per-sale SUM(schedule amount_due) == net
  SELECT count(*) INTO n FROM (
    SELECT s.id, s.net_amount, COALESCE(SUM(i.amount_due),0) sd
    FROM sales s JOIN _chk c ON c.sale_no=s.sale_number
    LEFT JOIN installments i ON i.sale_id=s.id
    WHERE s.company_id=CO GROUP BY s.id, s.net_amount
  ) t WHERE t.sd <> t.net_amount;
  IF n<>0 THEN RAISE EXCEPTION 'CHECK c FAIL: schedule!=net for % sales', n; END IF;

  -- d) per-sale SUM(payments) == file received (incl 2 overpaid)
  SELECT count(*) INTO n FROM (
    SELECT s.id, c.received, COALESCE(SUM(p.amount),0) sp
    FROM sales s JOIN _chk c ON c.sale_no=s.sale_number
    LEFT JOIN payments p ON p.sale_id=s.id
    WHERE s.company_id=CO GROUP BY s.id, c.received
  ) t WHERE t.sp <> t.received;
  IF n<>0 THEN RAISE EXCEPTION 'CHECK d FAIL: payments!=received for % sales', n; END IF;

  -- e) batch-2 totals
  SELECT SUM(s.net_amount), (SELECT SUM(p.amount) FROM payments p JOIN sales s2 ON s2.id=p.sale_id JOIN _chk c2 ON c2.sale_no=s2.sale_number WHERE s2.company_id=CO)
    INTO bn, br FROM sales s JOIN _chk c ON c.sale_no=s.sale_number WHERE s.company_id=CO;
  IF bn<>178275447 THEN RAISE EXCEPTION 'CHECK e FAIL: batch-2 net = % (want 178275447)', bn; END IF;
  IF br<>113122366 THEN RAISE EXCEPTION 'CHECK e FAIL: batch-2 received = % (want 113122366)', br; END IF;

  -- f) GRAND TOTAL FMH
  SELECT count(*), SUM(net_amount) INTO n, bn FROM sales WHERE company_id=CO AND status='active';
  IF n<>209 THEN RAISE EXCEPTION 'CHECK f FAIL: FMH active sales = % (want 209)', n; END IF;
  IF bn<>1378628647 THEN RAISE EXCEPTION 'CHECK f FAIL: FMH net = % (want 1378628647)', bn; END IF;
  SELECT SUM(p.amount) INTO br FROM payments p JOIN sales s ON s.id=p.sale_id WHERE s.company_id=CO AND s.status='active';
  IF br<>540289956 THEN RAISE EXCEPTION 'CHECK f FAIL: FMH received = % (want 540289956)', br; END IF;
  SELECT SUM(i.amount_due) INTO bn FROM installments i JOIN sales s ON s.id=i.sale_id WHERE s.company_id=CO AND s.status='active';
  IF bn<>1378628647 THEN RAISE EXCEPTION 'CHECK f FAIL: FMH schedule sum = % (want 1378628647)', bn; END IF;

  -- g) units state + fingerprint unchanged
  SELECT count(*) FILTER (WHERE status_id=SOLD), count(*) FILTER (WHERE status_id=AVAIL), count(*)
    INTO n, m, bn FROM units WHERE company_id=CO AND project_id=PROJ;
  IF n<>209 THEN RAISE EXCEPTION 'CHECK g FAIL: Sold units = % (want 209)', n; END IF;
  IF m<>243 THEN RAISE EXCEPTION 'CHECK g FAIL: Available units = % (want 243)', m; END IF;
  IF bn<>452 THEN RAISE EXCEPTION 'CHECK g FAIL: total units = % (want 452)', bn; END IF;
  SELECT md5(string_agg(unit_no||'|'||base_price||'|'||area||'|'||COALESCE(features->>'rate_per_sqft','-'), ',' ORDER BY unit_no))
    INTO fp FROM units WHERE company_id=CO AND project_id=PROJ;
  IF fp<>'9cc2e194e7f83a8fa1490bae2fa70c13' THEN RAISE EXCEPTION 'CHECK g FAIL: units fingerprint changed -> %', fp; END IF;

  -- h) exactly 2 over-paid (8-13, 4-12), no other negative across ALL FMH active sales
  SELECT count(*) INTO n FROM (
    SELECT s.id, un.unit_no, s.net_amount, COALESCE(SUM(p.amount),0) recv
    FROM sales s JOIN units un ON un.id=s.unit_id
    LEFT JOIN payments p ON p.sale_id=s.id
    WHERE s.company_id=CO AND s.status='active' GROUP BY s.id, un.unit_no, s.net_amount
  ) t WHERE t.recv > t.net_amount;
  IF n<>2 THEN RAISE EXCEPTION 'CHECK h FAIL: over-paid sales = % (want 2)', n; END IF;
  SELECT count(*) INTO n FROM (
    SELECT un.unit_no, s.net_amount, COALESCE(SUM(p.amount),0) recv
    FROM sales s JOIN units un ON un.id=s.unit_id
    LEFT JOIN payments p ON p.sale_id=s.id
    WHERE s.company_id=CO AND s.status='active' GROUP BY un.unit_no, s.net_amount
  ) t WHERE t.recv > t.net_amount AND t.unit_no NOT IN ('8-13','4-12');
  IF n<>0 THEN RAISE EXCEPTION 'CHECK h FAIL: % over-paid units other than 8-13/4-12', n; END IF;

  RAISE NOTICE 'ALL CHECKS PASSED (a-h): 30 sales, FMH=209, net=1378628647, received=540289956';
END $v$;

COMMIT;
